1	package com.loja.checkout.domain;
2	
3	import com.loja.checkout.domain.clube.NivelClube;
4	import com.loja.checkout.domain.cupom.Cupom;
5	import com.loja.checkout.domain.entrega.ModalidadeEntrega;
6	import com.loja.checkout.domain.pagamento.FormaPagamento;
7	import com.loja.checkout.domain.pagamento.ResultadoPagamento;
8	import com.loja.checkout.domain.regiao.Regiao;
9	import com.loja.checkout.web.dto.CheckoutRequest;
10	import com.loja.checkout.web.dto.ItemRequest;
11	import org.springframework.stereotype.Service;
12	
13	import java.math.BigDecimal;
14	import java.util.ArrayList;
15	import java.util.List;
16	
17	@Service
18	public class CheckoutService {
19	
20	    public Resumo calcular(CheckoutRequest req) {
21	        List<Item> itens = validarItens(req.itens);
22	        NivelClube nivel = parseEnum(req.nivelClube, NivelClube.class, CodigoErro.NIVEL_CLUBE_INVALIDO);
23	        Regiao regiao = parseEnum(req.regiao, Regiao.class, CodigoErro.REGIAO_INVALIDA);
24	        ModalidadeEntrega modalidade = parseEnum(req.modalidadeEntrega, ModalidadeEntrega.class, CodigoErro.MODALIDADE_INVALIDA);
25	
26	        BigDecimal pesoTotal = pesoTotal(itens);
27	        if (!modalidade.atende(pesoTotal)) {
28	            throw new PedidoInvalidoException(CodigoErro.MODALIDADE_INDISPONIVEL);
29	        }
30	
31	        Cupom cupom = null;
32	        if (req.cupom != null && !req.cupom.isEmpty()) {
33	            cupom = parseEnum(req.cupom, Cupom.class, CodigoErro.CUPOM_INVALIDO);
34	        }
35	
36	        FormaPagamento forma = parseEnum(req.formaPagamento, FormaPagamento.class, CodigoErro.FORMA_PAGAMENTO_INVALIDA);
37	        int parcelas = req.parcelas == null ? 1 : req.parcelas;
38	        if (!forma.parcelasValidas(parcelas)) {
39	            throw new PedidoInvalidoException(CodigoErro.PARCELAMENTO_INVALIDO);
40	        }
41	
42	        BigDecimal subtotalProdutos = Dinheiro.ajustar(subtotal(itens));
43	        BigDecimal freteBase = modalidade.frete(pesoTotal);
44	        BigDecimal frete = Dinheiro.ajustar(nivel.fretePago(freteBase));
45	
46	        BigDecimal descontoCupom = Dinheiro.ZERO;
47	        if (cupom != null) {
48	            Cupom.ContextoCupom ctx = new Cupom.ContextoCupom(subtotalProdutos, frete, itens);
49	            if (!cupom.aplicavel(ctx)) {
50	                throw new PedidoInvalidoException(CodigoErro.CUPOM_NAO_APLICAVEL);
51	            }
52	            descontoCupom = Dinheiro.ajustar(cupom.desconto(ctx));
53	        }
54	
55	        BigDecimal seguro = Dinheiro.ajustar(subtotalProdutos.multiply(regiao.aliquotaSeguro()));
56	        BigDecimal totalPedido = Dinheiro.ajustar(
57	                subtotalProdutos.subtract(descontoCupom).add(frete).add(seguro));
58	
59	        if (!forma.disponivel(totalPedido)) {
60	            throw new PedidoInvalidoException(CodigoErro.FORMA_PAGAMENTO_INDISPONIVEL);
61	        }
62	
63	        ResultadoPagamento pagamento = forma.calcular(totalPedido, parcelas);
64	        BigDecimal credito = nivel.credito(subtotalProdutos);
65	        boolean brinde = nivel.temBrinde(subtotalProdutos);
66	
67	        return new Resumo(
68	                subtotalProdutos,
69	                descontoCupom,
70	                frete,
71	                modalidade.prazoDias(),
72	                seguro,
73	                pagamento.ajuste(),
74	                pagamento.totalFinal(),
75	                pagamento.parcelas(),
76	                pagamento.valorParcela(),
77	                credito,
78	                brinde);
79	    }
80	
81	    private static List<Item> validarItens(List<ItemRequest> brutos) {
82	        if (brutos == null || brutos.isEmpty()) {
83	            throw new PedidoInvalidoException(CodigoErro.PEDIDO_INVALIDO);
84	        }
85	        List<Item> itens = new ArrayList<>(brutos.size());
86	        for (ItemRequest r : brutos) {
87	            if (r == null
88	                    || r.precoUnitario == null || r.precoUnitario.signum() <= 0
89	                    || r.quantidade == null || r.quantidade <= 0
90	                    || r.pesoKg == null || r.pesoKg.signum() <= 0) {
91	                throw new PedidoInvalidoException(CodigoErro.PEDIDO_INVALIDO);
92	            }
93	            itens.add(new Item(r.nome, r.precoUnitario, r.quantidade, r.pesoKg));
94	        }
95	        return itens;
96	    }
97	
98	    private static BigDecimal subtotal(List<Item> itens) {
99	        BigDecimal total = BigDecimal.ZERO;
100	        for (Item i : itens) {
101	            total = total.add(i.precoUnitario().multiply(BigDecimal.valueOf(i.quantidade())));
102	        }
103	        return total;
104	    }
105	
106	    private static BigDecimal pesoTotal(List<Item> itens) {
107	        BigDecimal total = BigDecimal.ZERO;
108	        for (Item i : itens) {
109	            total = total.add(i.pesoKg().multiply(BigDecimal.valueOf(i.quantidade())));
110	        }
111	        return total;
112	    }
113	
114	    private static <E extends Enum<E>> E parseEnum(String nome, Class<E> tipo, CodigoErro erro) {
115	        if (nome == null) throw new PedidoInvalidoException(erro);
116	        try {
117	            return Enum.valueOf(tipo, nome);
118	        } catch (IllegalArgumentException e) {
119	            throw new PedidoInvalidoException(erro);
120	        }
121	    }
122	}
