2	
3	import com.loja.checkout.domain.Dinheiro;
4	
5	import java.math.BigDecimal;
6	
7	public enum FormaPagamento {
8	
9	    PIX {
10	        @Override public boolean parcelasValidas(int parcelas) { return parcelas == 1; }
11	        @Override public boolean disponivel(BigDecimal totalPedido) { return true; }
12	        @Override public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
13	            BigDecimal desconto = Dinheiro.ajustar(totalPedido.multiply(new BigDecimal("0.05")));
14	            BigDecimal totalFinal = Dinheiro.ajustar(totalPedido.subtract(desconto));
15	            return new ResultadoPagamento(desconto.negate(), totalFinal, 1, totalFinal);
16	        }
17	    },
18	
19	    CARTAO {
20	        private final BigDecimal taxa = new BigDecimal("0.0199");
21	        private final int semJurosAte = 3;
22	        @Override public boolean parcelasValidas(int parcelas) { return parcelas >= 1 && parcelas <= 12; }
23	        @Override public boolean disponivel(BigDecimal totalPedido) { return true; }
24	        @Override public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
25	            if (parcelas <= semJurosAte) {
26	                BigDecimal parcelaValor = Dinheiro.ajustar(
27	                        totalPedido.divide(BigDecimal.valueOf(parcelas), Dinheiro.MC));
28	                BigDecimal ajuste = Dinheiro.ajustar(BigDecimal.ZERO);
29	                return new ResultadoPagamento(ajuste, Dinheiro.ajustar(totalPedido), parcelas, parcelaValor);
30	            }
31	            BigDecimal fatorN = BigDecimal.ONE.add(taxa).pow(parcelas, Dinheiro.MC);
32	            BigDecimal numerador = totalPedido.multiply(taxa).multiply(fatorN);
33	            BigDecimal denominador = fatorN.subtract(BigDecimal.ONE);
34	            BigDecimal parcelaValor = Dinheiro.ajustar(numerador.divide(denominador, Dinheiro.MC));
35	            BigDecimal totalFinal = Dinheiro.ajustar(parcelaValor.multiply(BigDecimal.valueOf(parcelas)));
36	            BigDecimal ajuste = Dinheiro.ajustar(totalFinal.subtract(totalPedido));
37	            return new ResultadoPagamento(ajuste, totalFinal, parcelas, parcelaValor);
38	        }
39	    },
40	
41	    BOLETO {
42	        private final BigDecimal tarifa = new BigDecimal("3.49");
43	        private final BigDecimal limite = new BigDecimal("1000");
44	        @Override public boolean parcelasValidas(int parcelas) { return parcelas == 1; }
45	        @Override public boolean disponivel(BigDecimal totalPedido) { return totalPedido.compareTo(limite) <= 0; }
46	        @Override public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
47	            BigDecimal totalFinal = Dinheiro.ajustar(totalPedido.add(tarifa));
48	            return new ResultadoPagamento(Dinheiro.ajustar(tarifa), totalFinal, 1, totalFinal);
49	        }
50	    };
51	
52	    public abstract boolean parcelasValidas(int parcelas);
53	    public abstract boolean disponivel(BigDecimal totalPedido);
54	    public abstract ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas);
55	}
